  ('5ed49118-a585-5024-af4a-bf7dbe42f81a', '22222222-2222-2222-2222-222222222203', 'mcq', '“有的”互换特性 有的A是B=有的B是A=有A→B=有B→A 模块一 形式逻辑 补充：三段论 （三）直言命题联立 口诀：共同话题，有的开始，逆否换位，首尾联立 什么玩意儿？ 模块一 形式逻辑 补充：三段论 【练习7】 甲：上周去医院，给我看病的医生竟然还在抽烟。 乙：所有抽烟的医生都不关心自己的健康， 而不关心自己健康的人也不会关心他人的健康。 甲：是的，不关心他人健康的医生没有医德， 我今后再也不会让没有医德的医生给我看病了。 根据上述信息，以下除了哪项，其余各项均可得出？', '[{"key": "A", "text": "甲认为他不会再找抽烟的医生看病。抽烟→不找这样的医生"}, {"key": "B", "text": "乙认为上周给甲看病的医生不会关心乙的健康。抽烟→不关心他人的健康"}, {"key": "C", "text": "甲认为上周给她看病的医生不关心医生自己的健康。抽烟→不关心自己的健康"}, {"key": "D", "text": "甲认为上周给她看病的医生不会关心甲的健康。抽烟→不关心自己的健康→不关心他人的健康"}, {"key": "E", "text": "乙认为上周给甲看病的医生没有医德。 形式化："}]'::jsonb, '', '', '逻辑/基础必修4-概念.pdf', 3, true, 87, null),
  ('15b280d5-8efe-5ea4-a2f4-aa5bbb9c5512', '22222222-2222-2222-2222-222222222203', 'short', '甲：医生抽烟；', null, '', '', '逻辑/基础必修4-概念.pdf', 5, true, 88, null),
  ('634a0c06-6b11-5e80-a69c-f28830a87f4f', '22222222-2222-2222-2222-222222222203', 'short', '乙：抽烟→不关心自己的健康→不关心他人的健康；', null, '', '', '逻辑/基础必修4-概念.pdf', 5, true, 89, null),
  ('31b30034-bb74-5f01-8aa2-9c4b40f60cef', '22222222-2222-2222-2222-222222222203', 'short', '甲：抽烟→不关心自己的健康→不关心他人的健康→ 没有医德→不找这样的医生 模块一 形式逻辑 补充：三段论 【练习7】', null, 'E', '题干信息：', '逻辑/基础必修4-概念.pdf', 5, true, 90, null),
  ('bcda97a4-5719-57e2-b3aa-2a1e19d8c6d8', '22222222-2222-2222-2222-222222222203', 'short', '甲：医生抽烟；', null, '', '', '逻辑/基础必修4-概念.pdf', 6, true, 91, null),
  ('f9e5726f-f7fb-5c65-8448-c6d51d56e781', '22222222-2222-2222-2222-222222222203', 'short', '乙：抽烟→不关心自己的健康→不关心他人的健康；', null, '', '', '逻辑/基础必修4-概念.pdf', 6, true, 92, null),
  ('3efa8ae6-4593-55f2-9779-00d6de1bf878', '22222222-2222-2222-2222-222222222203', 'mcq', '甲：抽烟→不关心自己的健康→不关心他人的健康→没有医德→不找这样的医生 A选项：符合(3)； B选项：符合(2)； C选项：符合(3)； D选项：符合(3)； E选项：乙的推理并未涉及“医德”，无法得出。 模块一 形式逻辑 补充：三段论 【练习8】 兰教授认为：不善于思考的人不可能成为一名优秀 的管理者，没有一个谦逊的智者学习占星术，占星 家均学习占星术，但是有些占星家却是优秀的管理 者。以下哪项如果为真，最能反驳兰教授的上述观 点？', '[{"key": "A", "text": "有些占星家不是优秀的管理者。"}, {"key": "B", "text": "有些善于思考的人不是谦逊的智者。"}, {"key": "C", "text": "所有谦逊的智者都是善于思考的人。"}, {"key": "D", "text": "谦逊的智者都不是善于思考的人。"}, {"key": "E", "text": "善于思考的人都是谦逊的智者。 形式化："}]'::jsonb, '', '', '逻辑/基础必修4-概念.pdf', 6, true, 93, null),
  ('630b23f8-e4bc-54a2-93c0-069f7fa8238d', '22222222-2222-2222-2222-222222222203', 'short', '┐善于思考→┐优秀管理者=优秀管理者→善于思考', null, '', '', '逻辑/基础必修4-概念.pdf', 7, true, 94, null),
  ('73678636-e3d6-5889-a478-70cf97e1a9f9', '22222222-2222-2222-2222-222222222203', 'short', '谦逊→┐占星术=占星术→┐谦逊', null, '', '', '逻辑/基础必修4-概念.pdf', 7, true, 95, null),
  ('15431446-18d1-5a93-9ed5-3c4b1e7ccd3e', '22222222-2222-2222-2222-222222222203', 'short', '占星家→占星术', null, '', '', '逻辑/基础必修4-概念.pdf', 7, true, 96, null),
  ('4fd98154-b850-5b17-81e8-bb489d72b4a9', '22222222-2222-2222-2222-222222222203', 'short', '有些占星家→优秀管理者 口诀：共同话题，有的开始，逆否换位，首尾联立 互换特性：有的A→B=有的B→A 串联可得：', null, '', '', '逻辑/基础必修4-概念.pdf', 7, true, 97, null),
