  ('40142d6d-581a-5c69-b95d-1363914d821d', '22222222-2222-2222-2222-222222222203', 'short', '有些占星家→优秀管理者。 综合可得：', null, '', '', '逻辑/基础必修4-概念.pdf', 8, true, 104, null),
  ('260187c1-dd5d-5a32-ad1c-dc73f7bad8f3', '22222222-2222-2222-2222-222222222203', 'short', '有些占星家→优秀管理者→思考=有些思考→占星家（互换特性）；', null, '', '', '逻辑/基础必修4-概念.pdf', 8, true, 105, null),
  ('8efe8620-df6a-5d1e-a3cb-9f79534b1d23', '22222222-2222-2222-2222-222222222203', 'short', '占星家→占星术→非谦逊。 由（5）（6）可得：有些思考→占星家→占星术→非谦逊，即有些善于思考的人不是谦逊的智者，与E 选项矛盾。故正确答案选E。 模块一 形式逻辑 补充：三段论 【三段论反推题型】', null, '', '', '逻辑/基础必修4-概念.pdf', 8, true, 106, null),
  ('b5780dde-04a0-55f7-9730-050f8da3825a', '22222222-2222-2222-2222-222222222203', 'short', '题型特征 实际上，三段论的反推题型是在推理过程中缺少了一个前提条件，需要把缺少的条件补 充上，从而构成传递的一种题型。', null, '', '', '逻辑/基础必修4-概念.pdf', 9, true, 107, null),
  ('acb13276-2a71-5bb0-81d1-e457d071c599', '22222222-2222-2222-2222-222222222203', 'mcq', '思路点拨 例如： ？ B→C 因此，A→C 这个推理中缺少一段“A→B”，将这个前提条件补充后，推理即可成立。 模块一 形式逻辑 补充：三段论 【练习9】 有学校提出将效仿免费师范生制度，提供减免学费等 优惠条件，以吸引成绩优秀的调剂生，提高医学人才 培养质量。有专家对此提出反对意见，医生是既崇高 又辛苦的职业，要有足够的爱心和兴趣才能做好，因 此，宁可招不满也不要招收调剂生。 以下哪项最可能是上述专家论断的假设？', '[{"key": "A", "text": "没有奉献精神，就无法学好医学。"}, {"key": "B", "text": "如果缺乏爱心，就不能从事医生这一崇高的职业。"}, {"key": "C", "text": "调剂生往往对医学缺乏兴趣。"}, {"key": "D", "text": "因优惠条件而报考医学的学生往往缺乏奉献精神。"}, {"key": "E", "text": "有爱心并对医学有兴趣的学生不会在意是否收费。 形式化："}]'::jsonb, '', '', '逻辑/基础必修4-概念.pdf', 9, true, 108, null),
  ('5f312b5e-ac53-58ae-833f-fd683f493215', '22222222-2222-2222-2222-222222222203', 'short', '前提1：医生 → 兴趣', null, '', '', '逻辑/基础必修4-概念.pdf', 10, true, 109, null),
  ('449b0cc1-fa62-5891-bbe2-05517e79c0f4', '22222222-2222-2222-2222-222222222203', 'short', '前提2：？', null, '', '', '逻辑/基础必修4-概念.pdf', 10, true, 110, null),
